//! Vespera's `Multipart` derive macro implementation.
//!
//! This is a re-implementation of `axum_typed_multipart`'s derive macro that
//! natively supports `#[serde(rename_all)]` and `#[serde(rename)]` attributes
//! for field name resolution in multipart form data.
//!
//! ## Why?
//!
//! `axum_typed_multipart`'s derive macro only reads `#[try_from_multipart(rename_all)]`
//! and ignores `#[serde(rename_all)]`. This causes a mismatch: the OpenAPI spec
//! (generated by `Schema` derive) shows camelCase field names, but the runtime
//! multipart parser expects snake_case Rust field names.
//!
//! ## Field Name Resolution Priority
//!
//! 1. `#[form_data(field_name = "...")]` — explicit override (highest priority)
//! 2. `#[serde(rename = "...")]` — serde field rename (deserialize side)
//! 3. `#[serde(rename_all = "...")]` (deserialize side) or `#[try_from_multipart(rename_all = "...")]` applied to Rust name
//! 4. Rust field name as-is (lowest priority)

mod attrs;
mod fields;
mod types;

use proc_macro2::TokenStream;
use quote::quote;
use syn::{DeriveInput, Fields};

use self::attrs::{extract_strict, extract_struct_default};
use self::fields::{FieldCodegen, process_fields};

/// Message of the `compile_error!` emitted when `vespera`'s `multipart`
/// feature is off (see [`feature_disabled_error`]).
const FEATURE_DISABLED_MSG: &str = "`#[derive(Multipart)]` (also emitted by `schema_type!(..., multipart)`) \
     requires vespera's `multipart` feature: it is on by default, so re-enable it after \
     `default-features = false` with vespera = { features = [\"multipart\"] }";

/// Expansion of `vespera::Multipart` when `vespera` is built **without** its
/// `multipart` feature: a single `compile_error!` spanned at the struct name,
/// so the user sees which feature to enable instead of unresolved
/// `vespera::multipart::...` paths inside generated code.
pub fn feature_disabled_error(input: &DeriveInput) -> TokenStream {
    syn::Error::new(input.ident.span(), FEATURE_DISABLED_MSG).to_compile_error()
}

/// Process the `#[derive(TryFromMultipart)]` macro input.
pub fn process_derive(input: &DeriveInput) -> TokenStream {
    let struct_name = &input.ident;
    let rename_all =
        crate::parser::extract_rename_all_for(&input.attrs, crate::parser::SerdeSide::Deserialize);
    let strict = match extract_strict(&input.attrs) {
        Ok(strict) => strict,
        Err(err) => return err.to_compile_error(),
    };
    let struct_default = extract_struct_default(&input.attrs);

    let fields = match &input.data {
        syn::Data::Struct(data) => match &data.fields {
            Fields::Named(named) => &named.named,
            _ => {
                return syn::Error::new_spanned(
                    &input.ident,
                    "Multipart only supports structs with named fields",
                )
                .to_compile_error();
            }
        },
        _ => {
            return syn::Error::new_spanned(
                &input.ident,
                "Multipart can only be derived for structs",
            )
            .to_compile_error();
        }
    };

    let cg = process_fields(fields.iter(), rename_all.as_deref(), strict, struct_default);
    if let Some(err) = cg.errors.iter().cloned().reduce(|mut all, err| {
        all.combine(err);
        all
    }) {
        return err.to_compile_error();
    }
    let (impl_generics, ty_generics, where_clause) = impl_generics(input, &cg.parsed_types);

    // Wildcard arm of the field-dispatch `match`: strict mode rejects an
    // unknown field name; non-strict ignores it.  Replaces the trailing
    // `else { ... }` of the previous `if __field_name__ == "..." else if`
    // chain.  Cold path: the owned name is allocated only on rejection.
    let unknown_field_arm = if strict {
        quote! {
            _ => {
                return std::result::Result::Err(
                    vespera::multipart::TypedMultipartError::UnknownField {
                        field_name: std::string::String::from(__field_name__)
                    }
                );
            }
        }
    } else {
        quote! { _ => {} }
    };

    let missing_name_fallback = if strict {
        quote! {
            return std::result::Result::Err(
                vespera::multipart::TypedMultipartError::NamelessField
            )
        }
    } else {
        quote! { continue }
    };

    let FieldCodegen {
        declarations,
        assignments,
        post_loop,
        idents,
        ..
    } = &cg;

    quote! {
        impl #impl_generics vespera::multipart::TryFromMultipartWithState<__VesperaS__> for #struct_name #ty_generics #where_clause {
            async fn try_from_multipart_with_state(
                __multipart__: &mut vespera::axum::extract::Multipart,
                __state__: &__VesperaS__,
            ) -> std::result::Result<Self, vespera::multipart::TypedMultipartError> {
                #(#declarations)*

                while let std::option::Option::Some(__field__) = __multipart__
                    .next_field().await
                    .map_err(vespera::multipart::TypedMultipartError::from)? {
                    // Count EVERY wire part against the request-wide `max_fields`
                    // cap up front — before name resolution / dispatch — so
                    // unknown parts (the `_ => {}` non-strict arm) and nameless
                    // parts cannot slip past the limit the per-field parsers
                    // formerly enforced only for known fields.
                    vespera::multipart::register_multipart_part()?;
                    // Wrap the raw axum field so EVERY byte a parser reads is
                    // metered against the request-wide `max_total_bytes` cap —
                    // even a hand-written custom `TryFromFieldWithState` cannot
                    // bypass the aggregate limit (it reads through MeteredField).
                    let __field__ =
                        vespera::multipart::MeteredField::__from_field(__field__);
                    // Borrowed `&str` — NLL ends the borrow on each match
                    // arm before `__field__` is consumed by the parser, so
                    // no per-field `String` allocation is needed.
                    let __field_name__ = match __field__.name() {
                        | std::option::Option::Some("")
                        | std::option::Option::None => #missing_name_fallback,
                        | std::option::Option::Some(__name__) => __name__,
                    };

                    // Dispatch by resolved field name — a `match` over the
                    // field-name string literals instead of an
                    // `if __field_name__ == "..." else if ...` chain.
                    match __field_name__ {
                        #(#assignments)*
                        #unknown_field_arm
                    }
                }

                #(#post_loop)*

                std::result::Result::Ok(Self { #(#idents),* })
            }
        }
    }
}

/// `impl` generics / type generics / `where` clause of the derived impl: the
/// struct's own parameters plus the `__VesperaS__` state parameter, `Send` on
/// every type parameter (the parse future holds the fields across `.await`)
/// and a `TryFromFieldWithState` bound on each parsed type that mentions one.
fn impl_generics(
    input: &DeriveInput,
    parsed_types: &[syn::Type],
) -> (TokenStream, TokenStream, TokenStream) {
    let mut generics = input.generics.clone();
    let type_params: Vec<syn::Ident> = generics.type_params().map(|p| p.ident.clone()).collect();
    generics
        .params
        .push(syn::parse_quote!(__VesperaS__: Send + Sync));
    let where_clause = generics.make_where_clause();
    for ident in &type_params {
        where_clause
            .predicates
            .push(syn::parse_quote!(#ident: Send));
    }
    let mut seen = std::collections::HashSet::new();
    for ty in parsed_types.iter().filter(|ty| {
        mentions_any(quote!(#ty), &type_params) && seen.insert(quote!(#ty).to_string())
    }) {
        where_clause.predicates.push(syn::parse_quote!(
            #ty: vespera::multipart::TryFromFieldWithState<__VesperaS__>
        ));
    }
    let (impl_generics, _, where_clause) = generics.split_for_impl();
    let (_, ty_generics, _) = input.generics.split_for_impl();
    (
        quote!(#impl_generics),
        quote!(#ty_generics),
        quote!(#where_clause),
    )
}

/// Whether `tokens` contains any of `idents` (a struct type parameter).
fn mentions_any(tokens: TokenStream, idents: &[syn::Ident]) -> bool {
    tokens.into_iter().any(|tree| match tree {
        proc_macro2::TokenTree::Ident(ident) => idents.contains(&ident),
        proc_macro2::TokenTree::Group(group) => mentions_any(group.stream(), idents),
        _ => false,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_feature_disabled_error_names_the_feature() {
        let input: syn::DeriveInput = syn::parse_str("struct MyForm { pub name: String }").unwrap();
        let code = feature_disabled_error(&input).to_string();
        assert!(code.starts_with(":: core :: compile_error !"), "{code}");
        assert!(code.contains("vespera's `multipart` feature"), "{code}");
        assert!(!code.contains("TryFromMultipartWithState"), "{code}");
    }

    #[test]
    fn test_process_derive_basic_struct() {
        let input: syn::DeriveInput =
            syn::parse_str("struct MyForm { pub name: String, pub age: i32 }").unwrap();
        let code = process_derive(&input).to_string();
        assert!(code.contains("TryFromMultipartWithState"));
        assert!(code.contains("MyForm"));
        assert!(code.contains("\"name\""));
        assert!(code.contains("\"age\""));
    }

    #[test]
    fn test_process_derive_with_option_field() {
        let input: syn::DeriveInput =
            syn::parse_str("struct MyForm { pub name: String, pub bio: Option<String> }").unwrap();
        let code = process_derive(&input).to_string();
        assert!(code.contains("TryFromMultipartWithState"));
        assert!(code.contains("Option :: None"));
    }

    #[test]
    fn test_process_derive_with_vec_field() {
        let input: syn::DeriveInput =
            syn::parse_str("struct MyForm { pub name: String, pub tags: Vec<String> }").unwrap();
        let code = process_derive(&input).to_string();
        assert!(code.contains("Vec :: new"));
        assert!(code.contains("push"));
    }

    #[test]
    fn test_process_derive_strict_mode() {
        let input: syn::DeriveInput =
            syn::parse_str("#[try_from_multipart(strict)] struct MyForm { pub name: String }")
                .unwrap();
        let code = process_derive(&input).to_string();
        assert!(code.contains("DuplicateField"));
        assert!(code.contains("UnknownField"));
        assert!(code.contains("NamelessField"));
    }

    #[test]
    fn test_process_derive_with_rename_all() {
        let input: syn::DeriveInput = syn::parse_str(
            r#"#[serde(rename_all = "camelCase")] struct MyForm { pub user_name: String }"#,
        )
        .unwrap();
        assert!(process_derive(&input).to_string().contains("\"userName\""));
    }

    #[test]
    fn test_process_derive_reads_deserialize_side_rename_all() {
        let input: syn::DeriveInput = syn::parse_str(
            r#"#[serde(rename_all(serialize = "SCREAMING_SNAKE_CASE", deserialize = "camelCase"))] struct MyForm { pub user_name: String }"#,
        )
        .unwrap();
        let code = process_derive(&input).to_string();
        assert!(code.contains("\"userName\""));
        assert!(!code.contains("\"USER_NAME\""));
    }

    #[test]
    fn test_process_derive_with_serde_default() {
        let input: syn::DeriveInput =
            syn::parse_str("#[serde(default)] struct MyForm { pub count: i32 }").unwrap();
        assert!(
            process_derive(&input)
                .to_string()
                .contains("unwrap_or_default")
        );
    }

    #[test]
    fn test_process_derive_with_field_default_fn() {
        let input: syn::DeriveInput =
            syn::parse_str(r#"struct MyForm { #[serde(default = "my_default")] pub val: String }"#)
                .unwrap();
        let code = process_derive(&input).to_string();
        assert!(code.contains("unwrap_or_else"));
        assert!(code.contains("my_default"));
    }

    #[test]
    fn test_process_derive_with_invalid_field_default_fn_emits_compile_error() {
        // A malformed `#[serde(default = "...")]` function path must surface as
        // a clean span-attached compile_error, NOT panic the macro. The test
        // running to completion proves the former `.expect(...)` panic is gone.
        let input: syn::DeriveInput = syn::parse_str(
            r#"struct MyForm { #[serde(default = "1 not a path")] pub val: String }"#,
        )
        .unwrap();
        let code = process_derive(&input).to_string();
        assert!(code.contains("compile_error"));
        assert!(code.contains("function path"));
    }

    #[test]
    fn test_process_derive_non_struct_errors() {
        let input: syn::DeriveInput = syn::parse_str("enum Foo { A, B }").unwrap();
        assert!(process_derive(&input).to_string().contains("compile_error"));
    }

    #[test]
    fn test_process_derive_tuple_struct_errors() {
        let input: syn::DeriveInput = syn::parse_str("struct Foo(String, i32);").unwrap();
        assert!(process_derive(&input).to_string().contains("compile_error"));
    }

    #[test]
    fn test_process_derive_form_data_field_name() {
        let input: syn::DeriveInput = syn::parse_str(
            r#"struct MyForm { #[form_data(field_name = "custom")] pub data: String }"#,
        )
        .unwrap();
        assert!(process_derive(&input).to_string().contains("\"custom\""));
    }

    #[test]
    fn test_process_derive_form_data_default() {
        let input: syn::DeriveInput =
            syn::parse_str("struct MyForm { #[form_data(default)] pub count: i32 }").unwrap();
        assert!(
            process_derive(&input)
                .to_string()
                .contains("unwrap_or_default")
        );
    }

    #[test]
    fn test_process_derive_non_strict_no_duplicate_check() {
        let input: syn::DeriveInput = syn::parse_str("struct MyForm { pub name: String }").unwrap();
        let code = process_derive(&input).to_string();
        assert!(!code.contains("DuplicateField"));
        assert!(!code.contains("UnknownField"));
    }

    // ── File-field upload-limit defaults (runtime) ───────────

    #[test]
    fn test_process_derive_file_field_without_limit_uses_runtime_default() {
        let input: syn::DeriveInput =
            syn::parse_str("struct Up { pub file: FieldData<NamedTempFile> }").unwrap();
        let code = process_derive(&input).to_string();
        assert!(
            code.contains("Option :: None"),
            "a file field without a limit should pass None to runtime default cap: {code}"
        );
    }

    #[test]
    fn test_process_derive_optional_file_field_without_limit_uses_runtime_default() {
        let input: syn::DeriveInput =
            syn::parse_str("struct Up { pub file: Option<FieldData<NamedTempFile>> }").unwrap();
        assert!(
            process_derive(&input)
                .to_string()
                .contains("Option :: None"),
            "an Option-wrapped file field without a limit should use runtime default cap"
        );
    }

    #[test]
    fn test_process_derive_file_field_with_limit_ok() {
        let input: syn::DeriveInput = syn::parse_str(
            r#"struct Up { #[form_data(limit = "10MiB")] pub file: FieldData<NamedTempFile> }"#,
        )
        .unwrap();
        let code = process_derive(&input).to_string();
        assert!(
            !code.contains("compile_error"),
            "a file field with an explicit size limit must compile: {code}"
        );
    }

    #[test]
    fn test_process_derive_file_field_with_unlimited_ok() {
        let input: syn::DeriveInput = syn::parse_str(
            r#"struct Up { #[form_data(limit = "unlimited")] pub file: FieldData<NamedTempFile> }"#,
        )
        .unwrap();
        assert!(
            !process_derive(&input).to_string().contains("compile_error"),
            "an explicit `unlimited` opt-out must compile"
        );
    }

    /// Pretty-printed derive output, or the bare `compile_error!` tokens.
    fn derive_pretty(src: &str) -> String {
        let input: syn::DeriveInput = syn::parse_str(src).unwrap();
        let tokens = process_derive(&input);
        syn::parse2::<syn::File>(tokens.clone())
            .map_or_else(|_| tokens.to_string(), |file| prettyplease::unparse(&file))
    }

    /// Every `key = value` of `form_data` / `try_from_multipart` is read, in
    /// any order — an unrelated key before it no longer aborts the walk.
    #[rstest::rstest]
    #[case::form_data_limit_after_field_name(
        "multipart_form_data_limit_after_field_name",
        r#"struct F { #[form_data(field_name = "upload", limit = "10MiB", default)] pub data: String }"#
    )]
    #[case::form_data_field_name_after_limit(
        "multipart_form_data_field_name_after_limit",
        r#"struct F { #[form_data(limit = "1KiB", field_name = "upload")] pub data: String }"#
    )]
    #[case::strict_after_rename_all(
        "multipart_strict_after_rename_all",
        r#"#[try_from_multipart(rename_all = "camelCase", strict)] struct F { pub user_name: String }"#
    )]
    fn every_attribute_key_is_read(#[case] name: &str, #[case] src: &str) {
        insta::assert_snapshot!(name, derive_pretty(src));
    }

    /// A malformed or overflowing `limit` is a spanned compile error, never a
    /// silent `None` (runtime default cap) or a macro panic.
    #[rstest::rstest]
    #[case::lowercase_unit(
        "multipart_limit_lowercase_unit",
        r#"struct F { #[form_data(limit = "10mb")] pub data: String }"#
    )]
    #[case::fraction(
        "multipart_limit_fraction",
        r#"struct F { #[form_data(limit = "1.5MiB")] pub data: String }"#
    )]
    #[case::overflow(
        "multipart_limit_overflow",
        r#"struct F { #[form_data(limit = "99999999999999999999GiB")] pub data: String }"#
    )]
    #[case::multiplier_overflow(
        "multipart_limit_multiplier_overflow",
        r#"struct F { #[form_data(limit = "18446744073709551615KiB")] pub data: String }"#
    )]
    #[case::non_string(
        "multipart_limit_non_string",
        r"struct F { #[form_data(limit = 10)] pub data: String }"
    )]
    #[case::valueless(
        "multipart_limit_valueless",
        r"struct F { #[form_data(limit)] pub data: String }"
    )]
    #[case::malformed_attribute(
        "multipart_form_data_malformed",
        r"struct F { #[form_data(limit = )] pub data: String }"
    )]
    #[case::malformed_container_attribute(
        "multipart_try_from_multipart_malformed",
        r"#[try_from_multipart(strict = )] struct F { pub data: String }"
    )]
    fn invalid_limit_is_a_compile_error(#[case] name: &str, #[case] src: &str) {
        let out = derive_pretty(src);
        assert!(out.contains("compile_error"), "{out}");
        insta::assert_snapshot!(name, out);
    }

    /// `#[serde(skip)]` / `skip_deserializing` fields are never parsed from
    /// the form and start from their default — not a `MissingField` error.
    #[rstest::rstest]
    #[case::skip(
        "multipart_serde_skip",
        "struct F { pub name: String, #[serde(skip)] pub cache: Vec<u8> }"
    )]
    #[case::skip_deserializing_with_default_fn(
        "multipart_serde_skip_deserializing_default_fn",
        r#"struct F { #[serde(skip_deserializing, default = "seed")] pub n: u32 }"#
    )]
    fn skipped_fields_are_defaulted(#[case] name: &str, #[case] src: &str) {
        let out = derive_pretty(src);
        assert!(
            !out.contains("\"cache\"") && !out.contains("\"n\""),
            "{out}"
        );
        insta::assert_snapshot!(name, out);
    }

    /// Generic structs keep their parameters (and get the parse bounds).
    #[rstest::rstest]
    #[case::type_param(
        "multipart_generic_type_param",
        "struct F<T> { pub value: T, pub items: Vec<T>, pub name: String }"
    )]
    #[case::bounded_with_where(
        "multipart_generic_where_clause",
        "struct F<T: Clone, const N: usize> where T: Default { #[serde(default)] pub value: Option<T> }"
    )]
    fn generic_structs_are_supported(#[case] name: &str, #[case] src: &str) {
        insta::assert_snapshot!(name, derive_pretty(src));
    }

    #[rstest::rstest]
    #[case::bare("T", true)]
    #[case::nested_group("Wrapper<[T; 2]>", true)]
    #[case::path_with_punct("std::string::String", false)]
    #[case::other_group("[u8; 4]", false)]
    fn mentions_any_finds_type_params(#[case] ty: &str, #[case] expected: bool) {
        let tokens: TokenStream = ty.parse().unwrap();
        assert_eq!(
            mentions_any(
                tokens,
                &[syn::Ident::new("T", proc_macro2::Span::call_site())]
            ),
            expected
        );
    }

    #[test]
    fn test_process_derive_non_file_field_without_limit_ok() {
        // Non-file fields keep their prior behaviour — no limit required.
        let input: syn::DeriveInput =
            syn::parse_str("struct Up { pub name: String, pub tags: Option<String> }").unwrap();
        assert!(
            !process_derive(&input).to_string().contains("compile_error"),
            "non-file fields must not require a limit"
        );
    }
}
